/* ÚLTIMA TRANSMISSÃO V6.0 — campanha expandida. Roteiro original, sem dependências. */
'use strict';
const EXT_CHAPTERS=[
 {id:8,name:'A OUTRA MARGEM',tag:'Há alguém no fim da frequência',tone:'road',intro:[['LIA / RÁDIO','Porto Cinza chamou por socorro durante sete dias. Agora alguém respondeu — e sabe o nome de Daniel.'],['CLARA','Achei que a transmissão encerraria esta história. Ela só abriu outra porta.'],['LEVI / SINAL DISTANTE','Se querem a verdade, sigam os trilhos até o mar. Não confiem em nenhum mapa da Helix.'],['NINA','A voz dele está sobre a frequência que minha mãe usava. Isso não pode ser coincidência.']]},
 {id:9,name:'ANTES DAS SIRENES',tag:'As lembranças também mentem',tone:'memory',intro:[['CLARA / MEMÓRIA','Antes do surto, eu reconhecia cada janela da rua e pensava que isso era conhecer uma cidade.'],['DANIEL / MEMÓRIA','Você lembra do que aconteceu ou do que conseguiu suportar?'],['DORA / MEMÓRIA','Uma família não se mede pela quantidade de coisas que guarda. Mede-se por aquilo que conta a verdade.'],['CLARA','Se eu quiser salvar Daniel, preciso deixar de protegê-lo das perguntas.']]},
 {id:10,name:'ESTRADA DAS CINZAS',tag:'A segurança de uns pode ser a prisão de outros',tone:'road',intro:[['OMAR','A estrada é livre, até alguém inventar um pedágio.'],['HELENA','Um uniforme não transforma medo em autoridade. Eu deveria ter aprendido isso antes.'],['ROSA','Enterrei duas pessoas sem saber o nome delas. Não quero enterrar a cidade do mesmo jeito.'],['CLARA','Um refúgio que cobra silêncio não é um refúgio.']]},
 {id:11,name:'O PREÇO DE UMA CURA',tag:'Nem toda esperança cabe numa ampola',tone:'laboratory',intro:[['JOANA','O que temos não é uma cura. É uma chance pequena com riscos que precisamos explicar.'],['ÍRIS','Eu omiti isso uma vez. Não farei outra pessoa pagar pelo meu medo.'],['SOFIA','Samuel tem nome, idade e uma mãe. Não é o caso treze de nenhum relatório.'],['CLARA','Se a cidade aceitar uma mentira confortável, o amanhã vai nascer doente.']]},
 {id:12,name:'FILHOS DO BLOQUEIO',tag:'A geração que herdou nossas escolhas',tone:'school',intro:[['BENTO','No caderno novo eu escrevi também os que ainda estão vivos. Pode ser que precisem ser lembrados depois.'],['CECÍLIA','As crianças aprenderam o som das sirenes antes de aprender os dias da semana.'],['OLÍVIA','Se todo mundo pode desaparecer, por que os adultos continuam prometendo que voltam?'],['CLARA','Porque não sabemos outra forma de pedir que vocês confiem em nós.']]},
 {id:13,name:'A GUERRA DAS VOZES',tag:'Quem controla a história controla o medo',tone:'siege',intro:[['MARISA / TRANSMISSÃO','Esta é a segunda rede. Nenhum bairro ficará mudo enquanto houver baterias.'],['CAIO','As pessoas querem proteção, não discursos.'],['TOMÁS','Uma verdade editada para vencer uma guerra também é uma arma.'],['CLARA','Vamos descobrir se ainda existe uma maneira de vencer sem nos tornarmos aquilo que tememos.']]},
 {id:14,name:'O QUE NOS FOI TIRADO',tag:'Perdoar não é esquecer',tone:'memory',intro:[['MARA','Passei a vida dizendo que meu pai não sabia. Agora sei que ele sabia tudo e pedia meu silêncio.'],['DANIEL','Guardei informações de você, Clara. Não porque não confiasse. Porque sabia que você voltaria por mim.'],['CLARA','E eu voltei. Mas também havia outras pessoas esperando.'],['LIA','A transmissão final será feita com todos os que permanecerem. Não haverá outra depois.']]},
 {id:15,name:'DEPOIS DA ÚLTIMA NOITE',tag:'O que vale a pena salvar',tone:'tower',intro:[['BENTO','Você acha que, quando tudo acabar, alguém vai querer ler nossos nomes?'],['CLARA','Acho que alguém vai precisar deles para entender por que continuamos.'],['LEVI','A maré está subindo. Temos três caminhos e nenhuma garantia.'],['LIA','O microfone está aberto. Agora não é só a voz de Clara. É a cidade inteira que precisa escolher.']]}
];
const EXT_CAST=[
 ['alice','Alice Duarte','Mãe de Nina / ex-operadora de rádio','Desapareceu antes do surto. Foi recrutada para criptografar pedidos de evacuação e vive com a culpa pelas mensagens retidas.'],
 ['yuri','Yuri Kato','Maquinista / guardião dos trilhos','Mantém uma locomotiva alimentada com combustível improvisado. Sua mulher morreu num bloqueio e ele não aceita ordens militares.'],
 ['marta','Marta Silveira','Enfermeira / antiga colega de Sofia','Sabe quem autorizou a transferência dos pacientes. Teme que revelar os nomes destrua a única amizade que lhe restou.'],
 ['elias','Elias Ferreira','Responsável por uma cozinha comunitária','Não pede fé a ninguém. Acredita que partilhar comida é a única prova de que a humanidade não terminou.'],
 ['omar','Omar Abreu','Guia das estradas / contrabandista','Conhece cada desvio e cada comprador de remédios. Já salvou famílias e já vendeu informações sobre outras.'],
 ['mara','Mara Antunes','Engenheira / filha de Vítor','Projetou um sistema de quarentena usado pelo pai sem seu consentimento. Quer testemunhar, mas teme ser condenada com ele.'],
 ['levi','Levi Moura','Operador do navio Aurora','Respondeu à transmissão de Clara. O barco que comanda só comporta parte dos refugiados, e essa conta o está destruindo.'],
 ['dora','Dora Mendes','Mãe de Clara e Daniel / lembranças','Morreu anos antes da epidemia. Suas cartas reaparecem como pistas, sem oferecer respostas prontas.'],
 ['gabriel','Gabriel Leal','Ex-tenente / escolta de civis','Cumpriu uma ordem que isolou um distrito inteiro. Sabe identificar um massacre antes de ele acontecer novamente.'],
 ['cecilia','Cecília Reis','Professora / protetora das crianças','Transformou a escola em lugar de luto, alfabetização e segurança. Recusa-se a deixar que os jovens sejam usados como moeda de troca.'],
 ['joana','Dra. Joana Costa','Imunologista / pesquisadora independente','Tem dados para contestar a Helix, mas se recusa a prometer resultados que ainda não existem.'],
 ['samuel','Samuel Vieira','Adolescente infectado / testemunha','Tem medo de perder a consciência e ser tratado como ameaça. Antes do surto queria aprender a tocar violão.'],
 ['rosa','Rosa Almeida','Líder comunitária / sobrevivente mais velha','Construiu o primeiro refeitório da zona costeira. Não acredita em heróis, apenas em vizinhos que cumprem a palavra.'],
 ['caio','Caio Neves','Líder da Frente da Ordem','Promete segurança por meio de cercas, racionamento e obediência. Acredita sinceramente que o caos justifica seus métodos.'],
 ['estela','Estela Brandão','Arquivista do Instituto Helix','Catalogou relatórios apagados. Escondeu um arquivo que pode salvar vidas, mas ele também contém nomes de voluntários.'],
 ['olivia','Olívia Mendes','Menina de nove anos / filha de Daniel','Daniel a manteve afastada de Porto Cinza para protegê-la. Clara descobre que é tia num momento em que não consegue prometer segurança.'],
 ['julia','Júlia Nóbrega','Mãe de Olívia / ex-companheira de Daniel','Confiou a filha a uma escola costeira. Não perdoa Daniel por desaparecer, embora saiba por que ele fugiu.'],
 ['tereza','Tereza Falcão','Presidente do conselho da Helix','Aceitou sacrificar pacientes em nome da contenção. Tenta comprar uma versão da verdade em que sempre foi necessária.'],
 ['luiza','Luiza Cardoso','Adolescente / voz da rádio escolar','Transforma fios e baterias num sistema de mensagens. Tem coragem de falar ao vivo, mas teme que alguém reconheça a voz.'],
 ['henrique','Henrique Pires','Bombeiro / chefe da evacuação','Tem uma lista de pessoas que não conseguiu retirar de um túnel. Continua levando a lista consigo mesmo quando já sabe os nomes de cor.']
].map(([id,name,role,bio])=>({id,name,role,bio}));
const EXT_BEATS=[];
function beat(ch,title,region,x,y,who,story,dialogue,options){
 const position=EXT_BEATS.filter(z=>z.chapter===ch).length+1;
 EXT_BEATS.push({chapter:ch,title,region,x,y,hint:`Investigue ${region.toLowerCase()} e encontre ${who.split(' / ')[0]}.`,speaker:who,tone:EXT_CHAPTERS[ch-8].tone,story,
 scenes:dialogue.map(([a,b])=>[a,b]),options:options.map(([title,flag,aftermath,person,delta,resource,lock],i)=>({id:`c${ch}m${position}_${i+1}`,title,detail:resource?.text||'Uma escolha irreversível; o destino de outras pessoas poderá mudar.',aftermath,effects:{flag,xp:55+(i===0?10:0),trust:person?{[person]:delta??(i===2?-18:14)}:undefined,...resource?.effects},requires:Object.fromEntries(Object.entries(resource?.effects||{}).filter(([k,v])=>['food','water','medkit','ammo'].includes(k)&&v<0).map(([k,v])=>[k,-v])),...lock?{requiresFlagAny:lock}:{}}))});
}
// CAPÍTULO 8 — A OUTRA MARGEM
beat(8,'O trem que ainda espera','Pátio Ferroviário',3680,510,'YURI','Uma locomotiva conserva o último tanque de combustível do distrito. Ela pode levar as famílias à costa, mas pessoas fragilizadas aguardam remédios na plataforma.',[['YURI','Minha esposa estava nesse trem quando as cancelas fecharam. Nunca mais abri a cabine para ninguém.'],['CLARA','Não posso pedir que esqueça. Só posso perguntar se quer salvar quem chegou depois.'],['YURI','Olhe nos olhos dessas famílias antes de responder.']],[[ 'Reservar o trem para famílias e feridos','trainFamilies','Yuri abre a porta do vagão e encontra uma manta infantil exatamente como a de sua esposa. Ele a dobra sem dizer nada.','yuri',20,{text:'O trem partirá mais lento; as famílias terão prioridade.',effects:{food:-1}}],['Dividir os vagões com equipes de resgate','trainShared','A locomotiva transporta pessoas e equipamentos. As negociações custam horas, mas preservam a possibilidade de voltar.','helena',10],['Tomar a locomotiva por ordem de emergência','trainSeized','A chave está na mão de Clara. Yuri permanece imóvel na plataforma, lembrando o som da cancela que nunca voltou a abrir.','yuri',-30]]);
beat(8,'A carta que não chegou','Correios da Enseada',4050,740,'ESTELA','No depósito postal, cartas de familiares foram confiscadas pela Helix. Uma é dirigida a Clara, com caligrafia de Daniel e data posterior ao desaparecimento.',[['ESTELA','Guardei o envelope porque reconheci o sobrenome. Não sabia se teria coragem de entregar.'],['CLARA','Você sabia que ele estava vivo?'],['ESTELA','Eu sabia apenas que ainda tentava escrever para você.']],[[ 'Ler todas as cartas com as famílias','lettersReturned','O pátio se enche de vozes lendo o que parecia perdido. Uma mãe descobre que o filho a procurou até o último dia.','estela',18],['Preservar somente a carta de Daniel','letterDaniel','A letra do irmão é familiar, mas a caixa de cartas atrás de Clara continua sem donos.','daniel',12],['Entregar o depósito à guarda sem abri-lo','lettersConfiscated','Os envelopes são lacrados novamente. Clara recebe um recibo e nenhum nome.','estela',-22]]);
beat(8,'Maré de promessas','Estaleiro da Costa',4540,550,'LEVI','O operador Levi oferece vagas no navio Aurora, mas não há lugar para todos. Uma lista de passageiros está sendo escrita antes de qualquer votação.',[['LEVI','Posso prometer sessenta lugares e já tenho noventa nomes.'],['CLARA','Se começar pelo nome de quem tem mais armas, nunca vai faltar uma justificativa.'],['LEVI','Então me diga qual é a forma justa de decidir quem fica.']],[[ 'Organizar uma lista pública de prioridades','manifestPublic','As pessoas discordam, discutem e acabam ajudando a contar cadeiras. Pela primeira vez a lista não pertence a uma só pessoa.','levi',20],['Sortear vagas com testemunhas','manifestLottery','Alguns abraçam desconhecidos. Outros choram por perder uma oportunidade que nunca lhes foi prometida.','rosa',8],['Aceitar a lista sigilosa do capitão','manifestSecret','O convés permanece calmo porque ninguém sabe quem ficará em terra. A tranquilidade tem prazo de validade.','levi',-20]]);
beat(8,'Um sinal com a voz dela','Estação Costeira',4800,910,'ALICE','Nina ouve uma voz que julgava morta. Alice, sua mãe, operava transmissões de evacuação para Helix; agora pede que o sinal seja mantido em segredo.',[['NINA','Eu aprendi a consertar rádios esperando por essa voz.'],['ALICE','Não escondi a minha vida. Escondi a sua localização.'],['CLARA','Nenhuma de vocês merece uma conversa decidida por mim.']],[[ 'Permitir que mãe e filha conversem sozinhas','aliceReunited','Nina larga o rádio no chão pela primeira vez. O silêncio entre as duas é cheio de perguntas, não de abandono.','nina',22],['Registrar o depoimento antes do reencontro','aliceRecorded','Alice fala dos canais bloqueados. Nina escuta sem interromper, mas leva o aparelho consigo ao sair.','tomas',14],['Cortar o sinal por suspeita de armadilha','aliceCut','A voz se apaga no momento em que tenta dizer “eu nunca deixei de...”. Nina não olha mais para Clara.','nina',-35]]);
beat(8,'O rapaz que não treme','Observatório Abandonado',4410,1260,'SAMUEL','Samuel foi mordido há dias, mas ainda consegue conversar normalmente. O grupo quer isolá-lo antes que a noite caia.',[['SAMUEL','Não quero que me chamem de milagre. Quero que me chamem pelo nome.'],['SOFIA','Não sei o que vai acontecer com ele. Isso não nos dá direito de tratá-lo como objeto.'],['CLARA','O medo de uma cidade inteira está olhando para um garoto.']],[[ 'Acolher Samuel com cuidados voluntários','samuelSheltered','Samuel adormece ouvindo alguém cantar num quarto ao lado. É a primeira noite em que não está acorrentado.','sofia',18],['Montar uma observação isolada e transparente','samuelObserved','A porta fica aberta durante o dia. Samuel escolhe os horários em que quer conversar.','joana',12],['Entregar Samuel à equipe de contenção','samuelTransferred','O carro parte sem sirene. Clara ouve seu nome ser chamado até a curva.','sofia',-26]]);
beat(8,'As primeiras duas luzes','Farol das Gaivotas',4970,1510,'LEVI','Do alto do farol, duas comunidades pedem ajuda ao mesmo tempo. O rádio tem energia para uma transmissão longa ou duas mensagens breves.',[['LEVI','Uma luz vem da colina; outra da enseada. Elas não sabem que estamos vendo as duas.'],['LIA','O tempo de resposta é curto. Depois a tempestade cobre tudo.'],['CLARA','Escolher quem escuta primeiro não deveria significar escolher quem deixa de existir.']],[[ 'Dividir a transmissão entre os dois bairros','lightBoth','O primeiro sinal é fraco. A segunda comunidade responde batendo metal em janelas. Ao menos sabem que foram ouvidas.','lia',18],['Orientar primeiro as famílias do interior','lightInland','Crianças começam a atravessar o campo com lanternas. Na enseada, a outra luz pisca duas vezes e apaga.','rosa',8],['Concentrar energia no navio Aurora','lightShip','O navio encontra a rota. A costa fica mais escura, e a rádio passa a receber pedidos sem resposta.','levi',-12]]);
// CAPÍTULO 9 — ANTES DAS SIRENES
beat(9,'O aniversário sem fotografia','Casa dos Mendes',960,180,'DORA / MEMÓRIA','Clara encontra a fita do aniversário de Daniel. Uma discussão que ela nunca entendeu antecedeu a primeira viagem dele à Helix.',[['DORA / MEMÓRIA','Apague a vela, Daniel. Não precisa pedir para ser corajoso.'],['DANIEL / MEMÓRIA','Eu só queria que a Clara ficasse para ouvir a música.'],['CLARA','Eu me lembro de sair. Não me lembro de por que ele parou de cantar.']],[[ 'Ouvir a fita completa, mesmo que doa','doraTape','A última faixa registra uma risada de família. Clara repete o som antes de guardar a fita ao lado da pistola.','daniel',18],['Guardar a fita para entregar a Daniel','doraGift','Ela embrulha a memória com cuidado. O aniversário permanece inacabado, mas agora existe alguém a quem levá-lo.','daniel',12],['Apagar a parte íntima antes de arquivar','doraEdited','O silêncio substitui a discussão. Clara sente alívio e imediatamente desconfia do próprio alívio.','daniel',-10]]);
beat(9,'A noite em que Sofia mentiu','Hospital Antigo',520,1090,'MARTA','Marta revela uma lista de pacientes transferidos antes da quarentena. Sofia assinou a ordem porque lhe garantiram que seriam atendidos.',[['MARTA','Fomos treinadas a obedecer ao formulário. O formulário dizia “transferência segura”.'],['SOFIA','Eu acreditei na assinatura. Havia pessoas nos corredores olhando para mim.'],['CLARA','A confiança pode ter sido usada contra você. Ainda assim precisamos contar o que aconteceu.']],[[ 'Acompanhar Sofia em um pedido público de desculpas','sofiaConfesses','Sofia lê um nome por vez. Não pede perdão. A sala escuta uma médica admitir aquilo que não pode reparar.','sofia',20],['Investigar os responsáveis antes de divulgar','sofiaInvestigates','Marta entrega o livro de plantões. Sofia vê sua assinatura e permanece sentada até o amanhecer.','marta',14],['Esconder a assinatura de Sofia','sofiaProtected','Clara dobra o documento. O gesto salva uma amizade hoje e cria outra dívida para amanhã.','sofia',5]]);
beat(9,'O uniforme de Helena','Quartel do Norte',2700,710,'GABRIEL','Gabriel recupera a gravação de uma ordem de bloquear a ponte. Helena reconhece a própria voz, mas a ordem original foi alterada.',[['GABRIEL','Eu estava lá. Achei que a rádio estivesse quebrada porque só repetia “não abram”.'],['HELENA','A ordem era retirar as pessoas da ponte. Alguém cortou a primeira metade.'],['CLARA','A gravação inteira não vai devolver ninguém. Pode impedir que aconteça outra vez.']],[[ 'Divulgar a gravação integral','helenaCleared','Helena ouve a própria voz sem cortes. Nem por isso consegue olhar para as famílias que ficaram para trás.','helena',22],['Entregar a gravação para investigação independente','helenaInquiry','Uma comissão de sobreviventes assume o arquivo. Não há absolvição automática nem condenação sem prova.','helena',10],['Destruir a gravação para evitar conflito','helenaBuried','Gabriel observa o arquivo sumir. No pátio, a história continua a ser contada pela metade.','gabriel',-18]]);
beat(9,'A voz antes do medo','Antiga Rádio AM',3900,1490,'ALICE','Alice conta a Nina sobre a última chamada que tentou transmitir antes de ser levada. Daniel estava no estúdio naquela noite.',[['ALICE','Não fui embora para começar outra vida. Fui levada porque continuei apertando o botão de transmissão.'],['NINA','Fiquei com raiva de você porque a raiva fazia menos barulho que a saudade.'],['CLARA','Daniel também estava lá. E guardou de mim o que ouviu.']],[[ 'Reunir as gravações de Alice e Daniel','voicesJoined','Duas vozes separadas por anos ocupam a mesma fita. Pela primeira vez contam a história do mesmo começo.','nina',18],['Deixar Nina decidir o que fazer com a prova','voicesNina','Nina pega o gravador com as duas mãos. Clara aceita não ser a protagonista da dor de outra pessoa.','nina',24],['Guardar o áudio sem contar a Nina','voicesHidden','A gravação está segura. A confiança de Nina, quando souber, talvez não esteja.','nina',-22]]);
beat(9,'O nome riscado','Arquivo da Prefeitura',2350,2040,'ESTELA','Um registro indica que Daniel solicitou retirada de uma menina chamada Olívia Mendes, mas nunca explicou a Clara quem ela era.',[['ESTELA','O sobrenome era o mesmo. Foi por isso que copiei a solicitação antes de destruírem o arquivo.'],['CLARA','Daniel nunca me contou sobre nenhuma criança.'],['ESTELA','Algumas mentiras servem para fugir. Outras são usadas como barricadas.']],[[ 'Seguir o nome de Olívia com discrição','oliviaTrace','Clara dobra a folha perto do coração. Uma vida desconhecida acaba de se tornar uma promessa.','daniel',14],['Compartilhar a pista com os aliados','oliviaShared','A busca ganha mais olhos e mais riscos. Todos prometem não pronunciar o nome pelo rádio.','sofia',10],['Exigir que Daniel explique antes de agir','oliviaWait','O arquivo é guardado. Em outro bairro, alguém continua esperando por uma pessoa que nunca recebeu o bilhete.','daniel',-10]]);
beat(9,'A promessa no cais','Cais da Infância',1700,2280,'DANIEL / MEMÓRIA','Clara revive a última conversa tranquila com Daniel. Ele pediu que ela nunca abandonasse um desconhecido para salvá-lo.',[['DANIEL / MEMÓRIA','Se algum dia você tiver que escolher entre mim e uma pessoa que você não conhece...'],['CLARA / MEMÓRIA','Nem termina. Não fala como se fosse desaparecer.'],['DANIEL / MEMÓRIA','Promete que vai ouvir o pedido de ajuda, mesmo que não venha da minha voz.']],[[ 'Aceitar a promessa que Daniel deixou','promiseStrangers','Clara percebe que procurar o irmão e proteger desconhecidos talvez não sejam escolhas opostas.','daniel',18],['Confessar que não sabe cumprir a promessa','promiseDoubt','A honestidade pesa mais que uma promessa impossível. Clara guarda o áudio sem inventar coragem.','sofia',12],['Recusar o peso de mais uma promessa','promiseRefused','A frase termina na gravação, mas Clara desliga o aparelho. Pela primeira vez escolhe não ouvir até o fim.','daniel',-20]]);
// CAPÍTULO 10 — ESTRADA DAS CINZAS
beat(10,'O pedágio dos vivos','Viaduto do Sul',3600,1990,'OMAR','Uma milícia exige medicamentos para deixar passar um comboio de famílias. Omar conhece um desvio que atravessa uma zona infestada.',[['OMAR','Já transportei caixas para esses homens. Sei quanto cobram de quem não tem nada.'],['ROSA','Minha neta está naquele carro. Você pode discutir a moral de um pedágio depois que ela passar.'],['CLARA','Não vou fingir que pagar agora não cria o próximo bloqueio.']],[[ 'Abrir um corredor civil sem pagar','tollBroken','As famílias passam sob a proteção de voluntários. O dono do bloqueio promete lembrar o rosto de Clara.','rosa',18],['Negociar passagem com suprimentos','tollPaid','Ninguém morre na passagem, mas o caminhão fica vazio. Omar chama isso de uma vitória que não caberá em fotografia.','omar',10,{text:'Consome dois medicamentos.',effects:{medkit:-2}}],['Abandonar o comboio e usar o desvio','tollLeft','O caminho secreto funciona. As luzes dos carros continuam presas à ponte quando Clara chega do outro lado.','rosa',-26]]);
beat(10,'A cozinha de Rosa','Praça do Caldeirão',3980,2360,'ROSA','Rosa mantém uma cozinha aberta para pessoas de ambos os lados do bloqueio. Caio exige uma lista de nomes para autorizar a distribuição.',[['ROSA','Uma panela não escolhe em quem vai caber a próxima colher.'],['CAIO','Sem cadastro, os infectados podem se misturar aos saudáveis.'],['CLARA','E com cadastro? Quantos famintos você está disposto a deixar do lado de fora?']],[[ 'Defender uma cozinha sem cadastro coercitivo','kitchenFree','Rosa serve comida a um homem com uniforme inimigo. Ele retira o capacete antes de agradecer.','rosa',25],['Criar registros voluntários e anônimos','kitchenConsent','Uma fila de nomes inventados vira uma fila de pessoas alimentadas. Caio não consegue transformá-la em inspeção.','elias',15],['Entregar a lista exigida por Caio','kitchenList','Os pratos são servidos mais depressa. Depois, dois nomes desaparecem da fila.','caio',18]]);
beat(10,'A estrada que Henrique fechou','Túnel do Sal',3070,2630,'HENRIQUE','Bombeiros removeram escombros e encontraram uma porta atrás da parede. Henrique sabe que crianças ficaram do lado de dentro quando ele ordenou a retirada.',[['HENRIQUE','Eu contei os capacetes. Não contei as mãos que seguravam os meus.'],['CECÍLIA','A culpa não é uma chave. Mas talvez você ainda seja o único que conhece a fechadura.'],['CLARA','Abra a porta. O resto a gente discute depois.']],[[ 'Entrar no túnel com Henrique','tunnelRescue','A primeira voz que responde não é de uma criança, mas de uma mulher que as manteve vivas. Henrique se ajoelha ao escutar.','henrique',24,{text:'Exige esforço e arrisca ferimentos.',effects:{health:-12}}],['Enviar uma equipe treinada e manter a vigília','tunnelTeam','As horas passam devagar. Ninguém chama os presos de perdidos enquanto o rádio continuar aceso.','helena',12],['Selar o túnel para proteger os bairros','tunnelSealed','A parede é reforçada. Henrique escreve o número de pessoas do outro lado na luva que não consegue tirar.','henrique',-35]]);
beat(10,'O passado de Omar','Mercado Afogado',4180,2820,'OMAR','Uma família reconhece Omar como o homem que vendeu a localização de um abrigo. Ele admite que recebeu combustível, mas diz ter usado tudo para salvar crianças.',[['MULHER NO MERCADO','Eu estava lá quando levaram meu pai. O homem que os guiou está aqui.'],['OMAR','Não posso desfazer a estrada que mostrei. Posso mostrar outra agora.'],['CLARA','Uma boa ação não compra o esquecimento de uma pessoa.']],[[ 'Exigir reparação e manter Omar sob vigilância','omarAccountable','Omar entrega a rota dos comboios aos moradores e aceita cozinhar para quem o acusa. Ninguém o perdoa naquela noite.','omar',16],['Entregar Omar à assembleia de sobreviventes','omarAssembly','O julgamento dura horas. Pela primeira vez Omar escuta o nome de quem perdeu por culpa dele.','rosa',18],['Proteger Omar ocultando sua participação','omarHidden','O guia permanece ao lado de Clara. A família o vê passar e entende o silêncio como resposta.','rosa',-24]]);
beat(10,'Um soldado sem ordem','Forte da Restinga',4680,2460,'GABRIEL','Gabriel possui munição suficiente para defender uma caravana, mas seus antigos subordinados querem recuperar o forte pela força.',[['GABRIEL','Eu sabia obedecer antes de saber perguntar. Foi assim que deixei metade do meu pelotão para trás.'],['HELENA','Não precisamos de um forte. Precisamos de passagem.'],['CLARA','Quem vai controlar as armas depois que sairmos daqui?']],[[ 'Desarmar o forte e distribuir proteção civil','fortCivil','Os antigos soldados viram escoltas voluntários. Um deles pede pela primeira vez que o chamem pelo nome.','gabriel',22],['Manter guarda temporária sob conselho','fortCouncil','Helena aceita guardar as chaves até o nascer do sol. Há testemunhas para cada caixa aberta.','helena',14],['Tomar o forte como centro de comando','fortCommand','A bandeira volta ao mastro. É mais fácil coordenar pela força; é mais difícil convencer alguém a confiar.','caio',12]]);
beat(10,'A fronteira não esquece','Marco Zero da Rodovia',5050,2910,'ROSA','O primeiro grupo de refugiados alcança o limite da zona isolada. Há espaço no transporte apenas para parte dos presentes.',[['ROSA','Meu filho acreditava que uma fronteira era uma linha. Hoje parece uma escolha escrita em gente.'],['CLARA','Não quero anunciar números sem dizer os nomes.'],['LEVI','Se perdermos a maré, talvez ninguém atravesse.']],[[ 'Organizar saídas em turnos e manter apoio no cais','borderRotations','A despedida é adiada para o segundo barco. Pela primeira vez o atraso se parece com esperança, não com abandono.','levi',20],['Priorizar crianças e pessoas enfermas','borderVulnerable','As primeiras vagas são ocupadas por quem mal consegue andar. Outros permanecem sem reclamar em voz alta.','sofia',20],['Embarcar apenas o grupo de Clara','borderInnerCircle','O motor parte. Do cais, Rosa não acena. Clara sabe que essa imagem voltará nos próximos dias.','rosa',-35]]);
// CAPÍTULO 11 — O PREÇO DE UMA CURA
beat(11,'O laboratório sem logotipo','Centro de Pesquisa Independente',4500,1910,'JOANA','Joana desenvolveu um protocolo experimental para conter sintomas, mas os dados são insuficientes. Tereza oferece recursos em troca de controle do estudo.',[['JOANA','Se eu disser “cura”, alguém vai arriscar a vida do filho antes de ler as contraindicações.'],['TEREZA','Podemos acelerar tudo se pararmos com essa conversa sobre consentimento.'],['CLARA','O tempo está acabando. A dignidade não deveria acabar primeiro.']],[[ 'Financiar um estudo voluntário e transparente','trialVoluntary','Joana lê o formulário inteiro, até o trecho mais difícil. Três pessoas assinam; outras duas decidem ir embora.','joana',24],['Publicar os dados brutos para análise independente','trialOpenData','Outras estações respondem com perguntas, não milagres. Pela primeira vez a pesquisa é maior que a Helix.','iris',20],['Aceitar os recursos de Tereza em sigilo','trialSecret','O laboratório volta a ter eletricidade. Ninguém sabe qual preço foi combinado enquanto as luzes acendem.','tereza',18]]);
beat(11,'Samuel quer escolher','Enfermaria do Porto',4760,1690,'SAMUEL','A infecção de Samuel avança lentamente. Joana oferece observar seu caso, mas uma guarda exige que ele seja entregue à contenção.',[['SAMUEL','Eu não quero morrer. Também não quero que a última coisa que eu veja seja uma cela.'],['SOFIA','Ele tem o direito de recusar um procedimento. Mesmo que isso nos assuste.'],['CLARA','Uma escolha verdadeira precisa continuar sendo dele.']],[[ 'Respeitar a decisão informada de Samuel','samuelConsent','Samuel assina com mãos trêmulas. Pede que guardem o violão ao lado da cama.','samuel',24],['Buscar tempo com tratamento de suporte','samuelCare','Sofia fica no quarto contando histórias de dias comuns. A doença não desaparece, mas o medo deixa de ocupar todo o espaço.','sofia',20],['Autorizar sedação e transferência contra sua vontade','samuelForced','O corredor fica quieto. Joana não chama aquilo de tratamento.','joana',-35]]);
beat(11,'A filha do diretor','Casa de Mara',4160,1880,'MARA','Mara entrega as plantas de contenção do Instituto Helix, assinadas por ela. Ela diz que o pai alterou o projeto depois da aprovação.',[['MARA','Desenhei portas para impedir a entrada do vírus. Ele transformou as portas numa maneira de impedir a saída de pessoas.'],['CLARA','Sua assinatura está em todas as páginas.'],['MARA','Por isso não estou pedindo para você me acreditar. Estou pedindo para guardar a planta.']],[[ 'Aceitar o testemunho público de Mara','maraWitness','Mara explica cada linha do projeto diante das famílias. Quando chega ao próprio nome, a voz não falha.','mara',25],['Pedir verificação independente das plantas','maraAudit','Os técnicos marcam as alterações em vermelho. Mara permanece até que todos terminem de perguntar.','estela',16],['Entregar as plantas ao pai em troca de vacinas','maraDeal','As caixas chegam ao abrigo, mas a original das plantas desaparece. Mara não consegue encarar Clara.','mara',-25]]);
beat(11,'As mãos de Marta','Hospital das Marés',3940,1570,'MARTA','A mesma enfermeira que participou das transferências clandestinas agora atende famílias sem suprimentos. O hospital recebe uma remessa destinada ao navio.',[['MARTA','Reconheço as pulseiras de identificação. Não consegui arrancá-las quando os ônibus partiram.'],['LEVI','Se eu entregar tudo aqui, o Aurora terá uma enfermaria vazia.'],['CLARA','São as mesmas pessoas. Só estão em lugares diferentes.']],[[ 'Dividir os kits entre hospital e navio','medicalSplit','Marta e Levi contam o conteúdo juntos. A soma é pequena, mas nenhuma porta fica totalmente vazia.','marta',19],['Dar prioridade aos pacientes mais graves','medicalCritical','O hospital atravessa a noite sem perder outra cama. No Aurora, Sofia prepara compressas com o pouco que resta.','sofia',15],['Guardar os insumos para a travessia','medicalShip','As caixas partem protegidas. Marta fecha a enfermaria uma hora antes.','marta',-20]]);
beat(11,'O arquivo dos efeitos adversos','Data Center Helix',3400,1570,'ESTELA','Estela revela exames alterados para ocultar complicações. Entre os registros há informações sobre Samuel e sobre as primeiras doses recebidas por Daniel.',[['ESTELA','Não apaguei esses dados quando mandaram. Só mudei os nomes das pastas.'],['ÍRIS','Se publicarmos sem proteger pacientes, vamos expor quem já foi usado.'],['CLARA','Talvez a verdade precise de mais cuidado do que uma mentira.']],[[ 'Proteger identidades e publicar os resultados','recordsAnonymized','As provas chegam à rádio sem revelar os rostos dos voluntários. Estela chora de alívio quando o arquivo é recebido.','estela',24],['Entregar dados completos a uma comissão médica','recordsCommission','A comissão assume a guarda dos exames. Joana exige que ninguém publique nomes sem autorização.','joana',18],['Usar os registros como moeda de negociação','recordsBlackmail','Tereza promete entregar combustível. O arquivo permanece intocado, mas as pessoas se tornam instrumentos.','tereza',12]]);
beat(11,'A dosagem impossível','Sala de Observação',4990,2160,'JOANA','Samuel e uma mulher desconhecida precisam da mesma dose experimental. Joana não consegue produzir mais antes do agravamento dos sintomas.',[['JOANA','Eu não vou escolher um rosto porque o conhecemos melhor.'],['SAMUEL','Pergunta para ela primeiro. Talvez ela tenha alguém esperando.'],['CLARA','Nenhuma resposta vai parecer suficiente quando a seringa estiver vazia.']],[[ 'Usar protocolo clínico e consentimento de ambos','doseEthical','Os médicos explicam os critérios. O resultado ainda é incerto, mas ninguém é reduzido a uma moeda.','joana',24],['Aplicar apenas medidas de suporte até haver mais dados','doseDelay','A espera é terrível. Samuel pede uma canção e Marta canta uma que tinha esquecido.','samuel',12],['Reservar a dose para Samuel por ser do grupo','doseFavoritism','Samuel recebe o tratamento e pergunta quem ficou sem ele. Clara não sabe responder.','sofia',-30]]);
// CAPÍTULO 12 — FILHOS DO BLOQUEIO
beat(12,'A menina atrás da cortina','Escola da Duna',3800,3150,'OLÍVIA','Clara encontra Olívia, filha de Daniel. A menina desconfia de quem diz conhecer seu pai e exige uma prova que só a família guardava.',[['OLÍVIA','Meu pai disse que ninguém com o mesmo sobrenome é obrigado a ser minha família.'],['CLARA','Ele tinha razão. Eu sou Clara, e tenho uma história sobre uma canção desafinada.'],['OLÍVIA','Se você souber a última palavra da música, talvez eu deixe você entrar.']],[[ 'Contar a verdade e pedir para conhecê-la','oliviaBond','Olívia responde cantando a última palavra. Clara descobre que a voz do irmão ainda vive numa criança que nunca viu.','olivia',28],['Deixar Júlia conduzir o reencontro','oliviaSlow','Júlia abre a porta, mas fica entre as duas. A confiança começa com o direito de não correr.','julia',18],['Exigir que a menina acompanhe a caravana','oliviaTaken','Olívia segura a cortina até os dedos perderem a força. A primeira lembrança que terá da tia será uma ordem.','olivia',-35]]);
beat(12,'O caderno de Bento','Pátio dos Girassóis',4050,3170,'BENTO','Bento guardou nomes e pequenos desenhos durante o surto. Caio pretende confiscá-lo para identificar famílias opositoras.',[['BENTO','Eu escrevi quem não voltou. Não escrevi para que alguém fosse procurar parentes e prendê-los.'],['CAIO','Informação evita infiltrações.'],['CLARA','Uma lista feita para lembrar pode ser usada para apagar.']],[[ 'Ocultar nomes sensíveis com consentimento dos familiares','namesGuarded','Bento reescreve os nomes em dois cadernos. Uma cópia fica com as famílias, outra com a rádio.','bento',25],['Criar um arquivo comunitário com acesso controlado','namesCommunity','As famílias decidem quais histórias podem ser lidas. O caderno deixa de ser de Bento e passa a ser delas.','rosa',20],['Entregar a lista completa à milícia','namesMilitia','As páginas mudam de mãos. Bento não escreve naquela noite.','bento',-35]]);
beat(12,'O recreio que falta','Ginásio da Memória',4360,3200,'CECÍLIA','A escola organiza uma festa para as crianças, mas há uma horda próxima. Os adultos discutem se vale a pena gastar energia em algo não essencial.',[['CECÍLIA','Uma infância sem brincadeira é só um treinamento para sobreviver a mais medo.'],['HENRIQUE','Se acendermos luzes, teremos que cuidar da saída também.'],['CLARA','Talvez seja possível proteger a alegria em vez de cancelá-la.']],[[ 'Organizar a festa com proteção e plano de fuga','festivalHope','As crianças riscam as calçadas de giz. Por uma hora, os adultos se lembram do som da alegria.','cecilia',22,{text:'Consome alimentos para a comemoração.',effects:{food:-2}}],['Fazer uma festa pequena, sem luzes','festivalQuiet','A música é quase um sussurro. Olívia e Bento dançam com os próprios passos.','olivia',15],['Cancelar e usar tudo nas barricadas','festivalCancelled','A escola fica mais segura. A caixa de giz continua fechada no armário.','cecilia',-20]]);
beat(12,'O menino e a sirene','Depósito da Escola',4650,3110,'LUIZA','Luiza construiu uma sirene que pode distrair a horda. O equipamento transmite também a voz de quem o acionar, revelando sua localização.',[['LUIZA','Meu pai dizia que rádio era uma maneira de não ficar sozinho.'],['NINA','O aparelho vai funcionar. Eu não consigo prometer o que vão ouvir do outro lado.'],['CLARA','Você não precisa provar coragem colocando a própria vida em risco.']],[[ 'Operar a sirene remotamente e proteger Luiza','luizaSafe','O som atravessa a rua sem que Luiza abandone a sala. Ela ri ao ouvir a máquina funcionar.','nina',18],['Permitir que Luiza decida com uma escolta','luizaAgency','Luiza escuta os riscos e escolhe ajudar. Nina segue a seu lado até a última porta.','luiza',22],['Obrigar Luiza a ligar a sirene sozinha','luizaExposed','A rua fica livre, mas Luiza não volta a falar ao microfone.','luiza',-35]]);
beat(12,'A carta de Júlia','Casa da Várzea',4830,3310,'JÚLIA','Júlia revela que Daniel sabia da existência de Olívia e escolheu afastar-se depois das ameaças. Ela teme que Clara repita o padrão da família.',[['JÚLIA','Eu não precisava de um herói. Precisava que ele chegasse em casa com o pão que prometeu.'],['CLARA','Passei dias procurando meu irmão. Não sabia que havia alguém esperando por um pai.'],['JÚLIA','Isso não faz de você culpada. Mas faz de você alguém que pode decidir agora.']],[[ 'Assumir um vínculo sem exigir perdão','juliaTrust','Clara promete contar a verdade sobre Daniel. Júlia responde que uma promessa pequena é melhor que uma grandiosa.','julia',25],['Pedir que Olívia escolha onde morar','juliaChoice','A menina diz que quer ficar perto da escola até a guerra terminar. Os adultos aceitam uma resposta sem heroísmo.','olivia',20],['Separar Olívia de Júlia por segurança','juliaSeparated','A criança entra no caminhão olhando para trás. Clara ouve a mesma pergunta até a curva: “quando ela vem?”','julia',-35]]);
beat(12,'A primeira aula de amanhã','Biblioteca Inundada',3500,2910,'CECÍLIA','Cecília encontra livros salvos da água e propõe transformá-los em escola. Caio oferece proteção se o currículo for submetido à milícia.',[['CECÍLIA','A primeira lição vai ser que vocês podem perguntar por quê.'],['CAIO','Perguntas não detêm infectados.'],['OLÍVIA','Mas elas ajudam a perceber quando alguém está mentindo.']],[[ 'Abrir uma escola independente e comunitária','schoolFree','A primeira aula começa com a pergunta de Olívia. Cecília anota no quadro: “O que é uma promessa?”.','cecilia',24],['Negociar segurança com supervisão civil','schoolCivic','Os guardas ficam na entrada, nunca diante do quadro. Cecília mantém as chaves.','rosa',14],['Aceitar o controle de conteúdo da milícia','schoolControl','Os livros permanecem secos, e as perguntas passam a ser feitas em sussurros.','caio',20]]);
// CAPÍTULO 13 — A GUERRA DAS VOZES
beat(13,'Duas rádios, duas verdades','Emissora da Fronteira',4930,910,'MARISA','Marisa divulga uma investigação sobre a Helix. Caio reage com uma edição que culpa os abrigos por espalhar o vírus.',[['MARISA','Eles cortaram um segundo da gravação para mudar quem apertou o gatilho.'],['TOMÁS','Se respondermos com outro corte, ninguém vai acreditar quando vier o resto.'],['CLARA','O mundo acabou rápido demais para perdermos também o direito aos fatos.']],[[ 'Publicar gravação integral e fontes verificáveis','radioUncut','Os ouvintes escutam os silêncios e as hesitações. Alguns deixam de concordar, mas nenhum pode dizer que recebeu só metade.','tomas',24],['Transmitir um debate com testemunhas','radioDebate','Helena enfrenta perguntas sobre o bloqueio. Mara responde sobre o pai. A verdade parece menos confortável ao vivo.','marisa',18],['Interromper à força o transmissor rival','radioSabotage','A outra voz desaparece. Do lado de fora, a cidade se pergunta por que precisa escolher quem pode falar.','lia',-26]]);
beat(13,'A noite do cerco','Viaduto Vermelho',3000,2930,'HENRIQUE','A Frente da Ordem cerca uma clínica alegando risco de contágio. Os médicos não conseguem retirar Samuel e outros pacientes.',[['HENRIQUE','Se deixarmos esses veículos fecharem as saídas, não haverá corredor amanhã.'],['SAMUEL','Eu não quero ser o motivo de um ataque.'],['CLARA','Você é o motivo de abrirmos a porta, não de fechá-la.']],[[ 'Garantir corredor médico supervisionado','siegeCorridor','Pacientes atravessam entre escudos improvisados. O primeiro guarda de Caio baixa a arma quando reconhece a própria irmã.','henrique',24],['Negociar cessar-fogo com observadores','siegeTruce','A clínica recebe água. A milícia recebe a promessa de informações verificadas. Ninguém finge que a confiança voltou.','helena',16],['Entregar pacientes como condição de paz','siegePatients','Os motores se afastam. Sofia olha as camas vazias e não aceita chamar aquilo de trégua.','sofia',-40]]);
beat(13,'A casa dos inimigos','Vila da Ferrugem',3600,2860,'ROSA','Um grupo de soldados desertores pede comida. Alguns participaram do bloqueio em que a família de Rosa sofreu perdas.',[['SOLDADO','Eu reconheço este lugar. Não vou pedir desculpas se isso só piorar tudo.'],['ROSA','Não precisa pedir. Precisa dizer o nome de quem deu a ordem.'],['CLARA','Alimentar alguém não significa absolver seus atos.']],[[ 'Oferecer alimento e exigir depoimentos','desertersWitness','A mesa fica tensa. Um soldado escreve o nome do comandante antes de tocar no prato.','rosa',24],['Criar trabalho comunitário supervisionado','desertersWork','Os desertores começam limpando os canais. As famílias decidem quando poderão entrar no refeitório.','gabriel',18],['Expulsar todos, inclusive os inocentes','desertersExiled','A rua fica vazia. O mais jovem caminha para fora carregando um cantil sem água.','rosa',-20]]);
beat(13,'O julgamento de Caio','Tribunal da Praça',4250,2700,'CAIO','Caio é capturado após uma ação contra abrigos. Ele afirma que seus métodos mantiveram famílias vivas, mas testemunhas apresentam desaparecimentos.',[['CAIO','Você sentiu medo quando as grades fecharam. Eu dei a esse medo uma função.'],['MARA','Uma ordem pode salvar hoje e destruir amanhã. Eu aprendi olhando os desenhos de meu pai.'],['CLARA','Não será outra pessoa armada que decidirá sozinha o seu destino.']],[[ 'Garantir julgamento público com direito de defesa','caioTrial','Caio é obrigado a ouvir os nomes de quem prendeu. A sentença fica para uma assembleia com testemunhas.','rosa',26],['Negociar troca de armas por proteção de civis','caioDeal','A troca evita um confronto imediato. Os familiares dos desaparecidos exigem saber quem autorizou o acordo.','helena',8],['Executar uma sentença sumária sem audiência','caioSummary','O silêncio na praça parece vitória por alguns segundos. Depois uma criança pergunta quem decidirá a próxima sentença.','rosa',-35]]);
beat(13,'O incêndio dos arquivos','Biblioteca de Sinais',3170,2200,'ESTELA','Um incêndio ameaça destruir o arquivo de Helix e as fichas das famílias. Só há tempo para retirar uma parte dos documentos.',[['ESTELA','Os relatórios provam tudo, mas as fichas dizem quem estava lá.'],['BENTO','Se eu salvar os nomes, depois podemos escrever de novo a história?'],['CLARA','Talvez. Se sobreviver alguém que se lembre do porquê.']],[[ 'Salvar os nomes e digitalizar provas disponíveis','archiveNames','Bento carrega uma caixa pesada demais para sua idade. Estela entrega-lhe um scanner portátil e decide ficar ajudando.','bento',22],['Salvar as provas originais da Helix','archiveProofs','Os documentos chegam às mãos de Tomás. Nas paredes queimadas, os nomes de famílias ainda são legíveis por uma noite.','tomas',20],['Usar água da escola para conter o fogo','archiveWater','As estantes resistem, mas a escola perde sua reserva. Cecília agradece e pergunta como alimentar os alunos.','cecilia',-10,{text:'A contenção exige água.',effects:{water:-3}}]]);
beat(13,'A transmissão que começou uma guerra','Torre das Duas Bandeiras',4700,2770,'LIA','Um grupo clandestino transmite falsos pedidos de ajuda para atrair sobreviventes. Nina consegue localizar a origem, mas reconhece a voz de Alice no sinal.',[['NINA','Alguém usa a assinatura de voz da minha mãe. Ela jamais chamaria pessoas para uma emboscada.'],['ALICE','Eu gravei frases de emergência. Eles podem estar usando arquivos antigos.'],['LIA','O próximo pedido vai ao ar em cinco minutos.']],[[ 'Expor a falsificação com prova técnica','signalForgery','A rádio toca as duas gravações lado a lado. O bairro descobre como o medo foi fabricado.','nina',24],['Avisar os bairros sem identificar Alice','signalProtectAlice','O aviso funciona. Alice perde uma chance de limpar o nome, mas não é transformada em alvo.','alice',20],['Apagar a frequência inteira','signalBlackout','A armadilha cala. Também calam os pedidos verdadeiros que dependiam da mesma antena.','lia',-25]]);
// CAPÍTULO 14 — O QUE NOS FOI TIRADO
beat(14,'O vídeo do pai','Sala de Arquivos Submersos',3290,3260,'MARA','Mara encontra uma gravação de Vítor admitindo que assinou o bloqueio e justificando a morte de civis como efeito colateral.',[['VÍTOR / GRAVAÇÃO','Não precisávamos de voluntários. Precisávamos de números que produzissem um resultado.'],['MARA','Passei a vida tentando provar que ele era melhor que os boatos.'],['CLARA','Você não precisa defender uma pessoa inteira para reconhecer que ela errou.']],[[ 'Preservar a gravação e ouvir Mara','vitorVideoKept','Mara pede para ouvir a fita mais uma vez. O homem que fala ainda é seu pai, mas já não controla o que ela sabe.','mara',24],['Enviar a prova à comissão de sobreviventes','vitorVideoTrial','Uma cópia parte para cada distrito. Mara assina a declaração sem pedir imunidade.','estela',18],['Ocultar o vídeo para proteger Mara','vitorVideoHidden','Ela abraça Clara, mas pergunta onde está a gravação ao fim do dia. A mentira tem o rosto de um favor.','mara',-12]]);
beat(14,'A última carta de Dora','Capela do Pinheiro',1100,3200,'DORA / MEMÓRIA','Clara encontra uma carta da mãe que não foi entregue após sua morte. Dora escreveu que seus filhos precisariam aprender a discordar sem desaparecer um do outro.',[['DORA / CARTA','Clara, você cuida dos outros como se só existisse amor quando alguém precisa ser salvo.'],['DORA / CARTA','Daniel, você foge de casa para não ser uma preocupação e deixa uma preocupação maior para trás.'],['CLARA','Ela conhecia a nossa família melhor do que conhecíamos um ao outro.']],[[ 'Ler a carta a Daniel e guardar as imperfeições','doraLetterShared','Daniel deixa Clara terminar sem interromper. A saudade não conserta o passado, mas permite que se olhem de novo.','daniel',25],['Ler a carta a Olívia como memória da avó','doraLegacy','Olívia pede para escrever uma resposta. Clara encontra um lápis quase gasto e o entrega.','olivia',24],['Guardar a carta sem abrir antigas feridas','doraLetterHidden','O envelope volta à bolsa. Clara o sente bater contra a perna a cada passo.','daniel',-8]]);
beat(14,'O homem na outra sala','Abrigo do Complexo Norte',2820,2210,'DANIEL','Daniel finalmente pode contar como chegou à Helix. Seu silêncio evitou uma prisão, mas deixou Olívia sem notícias e Clara à procura de um irmão que podia ter escrito.',[['DANIEL','Achei que, se eu voltasse, eles seguiriam vocês. Cada dia em silêncio tornava o próximo mais fácil.'],['CLARA','Eu não precisava que você fosse um herói. Precisava saber que estava vivo.'],['DANIEL','Eu também tinha medo de você olhar para mim e não reconhecer o que eu fiz.']],[[ 'Exigir a verdade completa e oferecer recomeço','danielReconciled','Daniel conta inclusive o que sabe que Clara vai odiar. No fim, ela se senta ao lado dele sem fingir que está tudo bem.','daniel',28],['Dar espaço e reconstruir a relação com tempo','danielDistance','Clara sai do quarto sem fechar a porta. Daniel entende que proximidade não pode ser exigida.','daniel',12],['Romper e impedir que Daniel fale à comunidade','danielEstranged','A voz dele fica trancada numa sala. Clara continua procurando o irmão que lembrava, agora sabendo onde ele está.','daniel',-40]]);
beat(14,'A decisão de Íris','Jardim da Clínica',4870,2400,'ÍRIS','Íris recebe uma oferta para fugir com os últimos dados da pesquisa. Joana solicita que permaneça e responda aos pacientes que sofreram efeitos adversos.',[['ÍRIS','Não há relatório que me devolva o momento em que podia ter dito não.'],['JOANA','Mas há pessoas vivas que merecem ouvir o que você sabe.'],['CLARA','Reparação não desfaz o dano. É o que fazemos depois de reconhecer o dano.']],[[ 'Apoiar uma comissão de reparação com Íris','irisRepairs','Uma mulher conta que perdeu a capacidade de segurar a caneca da filha. Íris anota sem interromper.','iris',28],['Abrir os dados e permitir que Íris parta','irisLeaves','Os arquivos ficam. Íris vai embora sabendo que deixou respostas e perguntas ainda sem dono.','joana',14],['Dar imunidade a Íris em troca da fórmula','irisImmunity','O tratamento fica disponível. As vítimas descobrem que ninguém será ouvido sobre seus ferimentos.','iris',-25]]);
beat(14,'O que Rosa enterrou','Cemitério da Praia',4200,3320,'ROSA','Rosa mostra a Clara um terreno onde famílias enterraram desconhecidos. Entre os pertences há um broche reconhecido por Alice.',[['ROSA','Escrevemos “desconhecido” porque não sabíamos. Nunca porque não importava.'],['ALICE','Minha irmã usava este broche. Eu disse a Nina que ela havia conseguido fugir.'],['CLARA','Então hoje alguém pode recuperar um nome, mesmo que não recupere a pessoa.']],[[ 'Identificar os mortos com respeito às famílias','gravesNamed','Os nomes substituem pedras numeradas. Alice permanece diante de uma sepultura até a luz desaparecer.','rosa',24],['Convidar familiares a decidir sobre os registros','gravesFamilies','Algumas famílias preferem nomes públicos, outras guardam a memória em segredo. Clara aceita ambas.','alice',18],['Manter o terreno fechado até após a evacuação','gravesSealed','O portão recebe uma corrente. Rosa deixa uma vela acesa do lado de fora.','rosa',-16]]);
beat(14,'Uma cidade para Olívia','Mirante dos Cedros',3740,3290,'OLÍVIA','Olívia pergunta a Clara se poderá voltar a ter uma casa depois que o mundo parar de mudar. Júlia e Daniel aguardam uma resposta juntos.',[['OLÍVIA','Quando crescer, vou contar que a cidade era feita de sirenes?'],['JÚLIA','Você também pode contar sobre o dia em que fizeram um bolo sem forno.'],['CLARA','Eu não sei como será o amanhã. Posso prometer que você terá o direito de escolher o que lembrar.']],[[ 'Garantir escola e comunidade para Olívia','oliviaFuture','Olívia desenha uma casa com portas largas, para que as pessoas possam entrar sem pedir licença.','olivia',26],['Preparar a família para viajar reunida','oliviaTravel','Daniel ajuda Júlia a dobrar um mapa. Os três discordam sobre o caminho e, pela primeira vez, isso parece uma família.','julia',18],['Mandar Olívia sozinha para um transporte especial','oliviaEvacuatedAlone','A menina embarca segurando o desenho de uma casa. Clara vê pela janela uma mão pequena que não acena.','olivia',-35]]);
// CAPÍTULO 15 — DEPOIS DA ÚLTIMA NOITE
beat(15,'A assembleia de Porto Cinza','Praça da Reconstrução',3270,2710,'ROSA','Os representantes dos bairros precisam decidir quem terá acesso aos alimentos e à rede de energia após o fim do bloqueio. Há medo de que o conselho seja uma nova milícia.',[['ROSA','Não peço que confiem em mim para sempre. Peço que saibam como me tirar daqui se eu estiver errada.'],['CAIO / RÁDIO','Uma cidade com muitas vozes não consegue agir quando está em perigo.'],['CLARA','Uma cidade com uma única voz pode esconder o perigo até ser tarde demais.']],[[ 'Criar conselho aberto, eleição e prestação de contas','newCouncil','A primeira resolução do conselho é estabelecer como substituir seus próprios representantes. Bento pede que isso também entre no caderno.','rosa',26],['Criar comando emergencial com fiscalização e prazo','newEmergency','A cidade concentra decisões por trinta dias e marca a data de sua revisão na parede do abrigo.','helena',12],['Aceitar governo permanente de uma liderança forte','newAutocracy','As filas ficam ordenadas. As pessoas aprendem depressa a não contestar a ordem do dia.','caio',24]]);
beat(15,'O livro que não se queima','Arquivo de Todos',2380,2950,'BENTO','Bento propõe publicar um livro com os desaparecidos e sobreviventes. Alguns temem que a lista permita perseguição e outros querem registrar os nomes completos.',[['BENTO','Se eu errar uma letra, posso apagar uma pessoa sem querer.'],['ESTELA','O arquivo pode ser corrigido. Só não pode fingir que nada aconteceu.'],['CLARA','Um registro vivo precisa aceitar que a verdade também é uma conversa.']],[[ 'Criar arquivo com consentimento e direito de correção','archiveConsent','Bento deixa páginas em branco para histórias que ainda serão contadas. Estela desenha um índice com lápis.','bento',26],['Publicar apenas os desaparecidos confirmados','archiveRestricted','As primeiras páginas chegam aos bairros sem ameaçar quem pediu sigilo. Algumas famílias pedem mais tempo.','estela',12],['Publicar dados completos sem consultar ninguém','archiveDox','O arquivo cresce depressa. Uma testemunha deixa o abrigo antes de ver o próprio nome exposto.','tomas',-28]]);
beat(15,'O último pedido de Samuel','Enfermaria do Amanhecer',4850,2020,'SAMUEL','Samuel pede que a cidade escolha como tratar os infectados conscientes no futuro. Joana mostra que ainda não existe garantia de cura, mas há acompanhamento possível.',[['SAMUEL','O que eu mais temi não foi virar um monstro. Foi vocês pararem de perguntar o que eu queria.'],['JOANA','Ainda temos mais perguntas que respostas. Isso é motivo para pesquisar, não para prender.'],['CLARA','Se uma cidade nasce de uma escolha, esta é uma das mais importantes.']],[[ 'Garantir direitos e acompanhamento voluntário','infectedRights','Samuel ajuda a escrever o protocolo. A primeira palavra é “pessoa”.','samuel',28],['Criar centros assistenciais com supervisão independente','infectedCenters','Os centros abrem com visitas permitidas e nomes nas portas. Sofia exige avaliação periódica.','joana',18],['Autorizar isolamento indefinido dos infectados','infectedForever','A rua fica mais tranquila. Samuel olha a nova placa no portão e não pergunta por quanto tempo.','samuel',-40]]);
beat(15,'A última prova','Câmara de Transmissão',4710,1020,'MARISA','Uma caixa contém cópias dos documentos originais da Helix. Tereza promete liberar o corredor marítimo se as provas nunca saírem da cidade.',[['TEREZA / RÁDIO','Vocês podem receber um navio ou uma investigação. Não terão os dois.'],['MARISA','Ela quer que a nossa segurança dependa de fingirmos que não aconteceu.'],['CLARA','Tenho medo de escolher a verdade e perder pessoas. Tenho medo maior de escolher o silêncio por elas.']],[[ 'Transmitir provas verificadas e proteger testemunhas','finalEvidencePublic','As transmissões cruzam o continente. No cais, a resposta de Tereza é apenas uma porta que se fecha.','marisa',26],['Enviar os arquivos à justiça externa com cópias locais','finalEvidenceCourt','Os arquivos são repartidos em três lugares, com guardiões diferentes. Uma mentira terá de vencer todos eles.','estela',18],['Trocar as provas pela passagem garantida','finalEvidenceSold','O navio se aproxima. Tomás recolhe os microfones e a comunidade percebe que a vitória tem uma parte que não pode contar.','tereza',24]]);
beat(15,'A despedida dos que ficaram','Praça da Luz',4540,2930,'HENRIQUE','O grupo divide-se entre os que querem atravessar o mar e os que pretendem reconstruir Porto Cinza. Uma tempestade torna a despedida urgente.',[['HENRIQUE','Não vou prometer que estaremos juntos. Posso deixar uma rota para quem quiser voltar.'],['JÚLIA','Minha filha tem direito a raízes e a viagens. Não precisamos escolher uma mentira bonita.'],['CLARA','Não existe um fim em que ninguém sente saudade.']],[[ 'Criar rede de apoio entre quem fica e quem parte','farewellBridge','No cais há duas filas, mas apenas uma lista de famílias. As pessoas prometem trocar notícias sem exigir que todos sigam juntos.','rosa',24],['Priorizar a evacuação e proteger os mais vulneráveis','farewellEvac','O barco parte com enfermaria e escola improvisadas. Quem fica recebe a frequência de retorno.','levi',18],['Fechar fronteiras e impedir a saída para reconstruir','farewellClosed','As ruas se enchem de gente, mas a escolha não foi de todos. O mapa das rotas é guardado sob chave.','caio',20]]);
beat(15,'A escolha que fica','Farol do Horizonte',5090,3170,'CLARA','Lia abre a frequência final. Há um navio no mar, um conselho aguardando a decisão e testemunhas prontas para contar o que sofreram. Clara não pode definir cada destino, mas pode decidir qual futuro defender.',[['LIA','A luz vermelha está acesa, Clara. Pode falar quando estiver pronta.'],['DANIEL','Não precisa terminar esta história sozinha.'],['OLÍVIA','Se você falar por todos, vai lembrar de dizer os nomes?'],['CLARA','Vou perguntar primeiro quem quer ser ouvido.']],[[ 'Liderar a travessia e manter as comunidades conectadas','v6EndingSea','Clara entrega o microfone a Levi, depois a Rosa e depois a Olívia. O mar não é um recomeço sem passado; é um caminho que não cabe numa voz só.','levi',20],['Transmitir a verdade e exigir responsabilização','v6EndingTruth','A história de Porto Cinza atravessa as ondas com documentos, hesitações e nomes. Ninguém a confunde com um conto de heróis.','lia',22],['Permanecer e fundar uma cidade livre','v6EndingHome','Clara desliga a sirene e abre as portas do abrigo. A primeira assembleia começa antes que todos tenham chegado.','rosa',20]]);
// 16 flashbacks interativos: o jogador decide que significado dar a uma memória,
// sem reescrever retroativamente os acontecimentos do passado.
