 30:{title:'MEMÓRIA / A ÚLTIMA VIAGEM',lines:[['CLARA / ANTES','Você sempre perde o trem, Daniel.'],['DANIEL / ANTES','Você sempre volta para esperar.'],['CLARA / PRESENTE','Desta vez os trilhos estão cheios de gente que nunca conhecemos.']],options:[['Lembrar a promessa de esperar pelos outros','rememberWait'],['Admitir que também tem medo de ficar','rememberFear'],['Guardar o nome da estação para encontrar Daniel','rememberStation']]},
 33:{title:'MEMÓRIA / A VOZ DE NINA',lines:[['NINA / CRIANÇA','Mãe, se você viajar, vai me ligar pelo rádio?'],['ALICE / ANTES','Vou inventar um sinal que só nós reconhecemos.'],['NINA / PRESENTE','Demorei anos para entender que nem toda ausência é abandono.']],options:[['Respeitar o sinal íntimo entre mãe e filha','rememberAliceTrust'],['Perguntar por que a ligação foi interrompida','rememberAliceQuestion'],['Guardar a lembrança sem intervir','rememberAliceSilence']]},
 36:{title:'MEMÓRIA / A COZINHA DE DORA',lines:[['DORA / ANTES','Se um prato sobra, a casa é grande o bastante para outra pessoa.'],['CLARA / CRIANÇA','E se não sobrar?'],['DORA / ANTES','A gente divide antes de contar.']],options:[['Aceitar a lição mesmo quando é difícil','rememberSharedTable'],['Reconhecer que Dora também errou','rememberMotherHuman'],['Conservar a lembrança sem promessas','rememberKitchen']]},
 39:{title:'MEMÓRIA / A ÚLTIMA TURMA',lines:[['CECÍLIA / ANTES','Quem terminou a redação pode desenhar o futuro.'],['OLÍVIA / ANTES','O meu tem uma casa que anda.'],['CLARA / PRESENTE','Talvez algumas crianças soubessem mais sobre recomeçar.']],options:[['Guardar os desenhos com os livros','rememberDreams'],['Contar às crianças sobre o passado','rememberSchool'],['Manter o passado só entre os adultos','rememberClosedPast']]},
 41:{title:'MEMÓRIA / A PROMESSA',lines:[['DANIEL / ANTES','Se eu precisar ir embora, você vai me odiar?'],['CLARA / ANTES','Vou te procurar antes de decidir.'],['CLARA / PRESENTE','Eu não sabia quanto tempo levaria essa procura.']],options:[['Manter a promessa apesar da dor','rememberBrother'],['Questionar por que Daniel não confiou nela','rememberBrotherQuestion'],['Aceitar que o reencontro não será como antes','rememberBrotherChange']]},
 43:{title:'MEMÓRIA / UMA PONTE ABERTA',lines:[['HELENA / ANTES','Não deixem ninguém atravessar sem autorização.'],['GABRIEL / ANTES','E se forem pessoas feridas?'],['HELENA / PRESENTE','Passei anos acreditando que ordem e dever eram a mesma coisa.']],options:[['Reconhecer o dano da obediência cega','rememberDuty'],['Considerar o risco dos soldados','rememberSoldiers'],['Ouvir testemunhas antes de julgar','rememberWitness']]},
 47:{title:'MEMÓRIA / O RETRATO DA FAMÍLIA',lines:[['DORA / ANTES','Fiquem juntos só por um segundo.'],['DANIEL / CRIANÇA','A Clara não quer sorrir.'],['CLARA / PRESENTE','Na foto parece que ninguém nunca esteve triste.']],options:[['Guardar a imagem sem idealizar a família','rememberImperfect'],['Contar a Olívia sobre a avó','rememberLegacy'],['Devolver a fotografia ao arquivo','rememberPhoto']]},
 49:{title:'MEMÓRIA / O PRIMEIRO EXPERIMENTO',lines:[['ÍRIS / ANTES','Precisamos de mais tempo e consentimento explícito.'],['VÍTOR / ANTES','A cidade não nos dará nenhuma das duas coisas.'],['ÍRIS / PRESENTE','Eu fiquei. Essa é a decisão pela qual preciso responder.']],options:[['Exigir que o estudo reconheça os danos','rememberScience'],['Investigar a ordem que Íris recebeu','rememberResponsibility'],['Focar somente no futuro do tratamento','rememberTreatment']]},
 52:{title:'MEMÓRIA / O DESENHO DE OLÍVIA',lines:[['OLÍVIA / ANTES','Papai, desenha uma estrada até a gente.'],['DANIEL / ANTES','Vou desenhar uma que não tenha portas fechadas.'],['OLÍVIA / PRESENTE','Não é a mesma coisa que uma estrada de verdade.']],options:[['Ouvir Olívia antes de oferecer proteção','rememberChildVoice'],['Prometer apenas o que pode cumprir','rememberSmallPromise'],['Assumir uma promessa que ainda não sabe cumprir','rememberBigPromise']]},
 55:{title:'MEMÓRIA / A PRIMEIRA VOZ DE LUIZA',lines:[['LUIZA / ANTES','Alô, estação escolar. Há alguém ouvindo?'],['NINA / ANTES','Eu estou. Você não precisa falar alto.'],['LUIZA / PRESENTE','Eu achei que uma voz pequena não chegava em lugar nenhum.']],options:[['Confiar o rádio a quem aprendeu a usá-lo','rememberYouthVoice'],['Ensinar segurança sem calar ninguém','rememberCarefulVoice'],['Evitar novas transmissões públicas','rememberMute']]},
 58:{title:'MEMÓRIA / A PRIMEIRA MENTIRA',lines:[['TOMÁS / ANTES','O arquivo mostra o que aconteceu.'],['EDITOR / ANTES','O público só vai escutar se você retirar as dúvidas.'],['TOMÁS / PRESENTE','Foi assim que aprendi a reconhecer uma história fácil demais.']],options:[['Preservar todas as versões do depoimento','rememberFullTape'],['Registrar o contexto de cada gravação','rememberContext'],['Dar prioridade a uma mensagem rápida','rememberUrgency']]},
