 66:{title:'MEMÓRIA / O NOME DE MÃE',lines:[['DORA / ANTES','Você não deve ser responsável por tudo, Clara.'],['CLARA / PRESENTE','Passei a vida tentando provar que ela estava errada.'],['OLÍVIA','Minha mãe diz que a gente pode sentir saudade e continuar vivendo.']],options:[['Compartilhar o luto com Olívia','rememberGriefShared'],['Escrever sobre Dora para Daniel','rememberGriefWritten'],['Guardar a carta em silêncio','rememberGriefQuiet']]},
 69:{title:'MEMÓRIA / A FOTOGRAFIA QUE FALTOU',lines:[['JÚLIA / ANTES','Você vai aparecer no aniversário dela, Daniel?'],['DANIEL / ANTES','Quando não puderem nos encontrar.'],['CLARA / PRESENTE','Ele confundiu ficar longe com proteger. Eu também já fiz isso.']],options:[['Ajudar Olívia a compreender sem justificar','rememberOliviaTruth'],['Ouvir a versão de Júlia primeiro','rememberJuliaVoice'],['Esperar que Daniel conte tudo sozinho','rememberDanielVoice']]},
