// Caminhos de roteiro desbloqueados por decisões antigas. Em uma nova campanha,
// o jogador pode descobrir opções que não estavam disponíveis antes.
function alternate(ch,number,suffix,title,detail,flag,aftermath,requires){
 const mission=EXT_BEATS.find(m=>m.chapter===ch&&m.options[0]?.id===`c${ch}m${number}_1`);
 if(!mission)throw Error(`Missing alternate: ${ch}/${number}`);
 mission.options.push({id:`c${ch}m${number}_${suffix}`,title,detail,aftermath,requiresFlagAny:requires,effects:{flag,xp:86}});
}
